import sys
from collections import deque

def main():
    sys.setrecursionlimit(1 << 25)
    n, m = map(int, sys.stdin.readline().split())
    adj = [[] for _ in range(n+1)]
    radj = [[] for _ in range(n+1)]
    for _ in range(m):
        u, v = map(int, sys.stdin.readline().split())
        adj[u].append(v)
        radj[v].append(u)

    k = int(sys.stdin.readline())
    path = list(map(int, sys.stdin.readline().split()))
    s, t = path[0], path[-1]

    dist = [float('inf')] * (n+1)
    dist[s] = 0
    q = deque([s])
    while q:
        u = q.popleft()
        for v in adj[u]:
            if dist[v] > dist[u] + 1:
                dist[v] = dist[u] + 1
                q.append(v)

    dist_t = [float('inf')] * (n+1)
    dist_t[t] = 0
    q = deque([t])
    while q:
        u = q.popleft()
        for v in radj[u]:
            if dist_t[v] > dist_t[u] + 1:
                dist_t[v] = dist_t[u] + 1
                q.append(v)

    min_rebuilds = 0
    max_rebuilds = 0
    current_path = None

    for i in range(k-1):
        u = path[i]
        v = path[i+1]
        if current_path is None:
            current_path = []
            q = deque([t])
            visited = [False] * (n+1)
            visited[t] = True
            while q:
                node = q.popleft()
                current_path.append(node)
                for neighbor in radj[node]:
                    if not visited[neighbor]:
                        visited[neighbor] = True
                        q.append(neighbor)
            current_path.reverse()
            if u not in current_path:
                max_rebuilds += 1
            else:
                idx = current_path.index(u)
                current_path = current_path[idx:]
        else:
            if v not in current_path:
                max_rebuilds += 1
            else:
                idx = current_path.index(v)
                current_path = current_path[idx:]

        if dist[u] + 1 != dist_t[v]:
            min_rebuilds += 1
            current_path = None
        else:
            if current_path is None or v not in current_path:
                min_rebuilds += 1
                current_path = None
            else:
                idx = current_path.index(v)
                current_path = current_path[idx:]

    print(min_rebuilds, max_rebuilds)

if __name__ == '__main__':
    main()
